  hover && !drag && !resizing && currentTool().mode === "Select" ? locate(candidates, hover) : [];

const renderLocators = (dpr: number) => {
  const live = liveLocators();
  if (live.length === 0) {
    rippleSince = undefined;
    return;
  }
  const now = performance.now();
  rippleSince ??= now;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

