import { readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

const sha = process.argv[2];
if (!sha) {
  console.error("usage: node wait-live.mjs <sha>");
  process.exit(1);
}

const envPath = join(homedir(), ".config", "stallion", "access-env");
const env = Object.fromEntries(
  readFileSync(envPath, "utf8")
    .split("\n")
    .filter((line) => line.includes("="))
    .map((line) => {
      const index = line.indexOf("=");
      return [line.slice(0, index), line.slice(index + 1)];
    }),
);

const url = "https://stallion.matthijs-f49.workers.dev/api/me/boards";
const deadline = Date.now() + 15 * 60 * 1000;

while (Date.now() < deadline) {
  const response = await fetch(url, {
    headers: {
      "CF-Access-Client-Id": env.CF_ACCESS_CLIENT_ID,
      "CF-Access-Client-Secret": env.CF_ACCESS_CLIENT_SECRET,
    },
  });
  const commit = response.headers.get("x-stallion-commit");
  console.log(`status=${response.status} commit=${commit}`);
  if (commit === sha) {
    console.log("live");
    process.exit(0);
  }
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 30000);
}

console.error("timed out waiting for the deploy");
process.exit(1);

