import { createRequire } from "node:module";
import { join } from "node:path";

const WT = "/home/mvhenten/development/stallion-worktrees/sticky-sonar";
const require = createRequire(join(WT, "package.json"));
const { chromium, devices } = require("playwright");
const { routeAccessHeaders } = await import(join(WT, "npm-scripts/env.mjs"));

const OUT = "/home/mvhenten/development/.tmp/stallion-small";
const ORIGIN = "https://stallion.matthijs-f49.workers.dev";

const errors = [];

const openBoard = async (context) => {
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && errors.push(`${page.url()}: ${m.text()}`));
  page.on("pageerror", (e) => errors.push(`${page.url()}: ${e}`));
  const id = `small${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  await page.goto(`${ORIGIN}/b/${id}`, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForTimeout(1200);
  return page;
};

const placeSticky = async (page, x, y) => {
  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) await more.click();
  await page.getByRole("button", { name: "Sticky note" }).first().click();
  await page.mouse.click(x, y);
  await page.waitForTimeout(300);
  await page.keyboard.type("Shadow proof");
  await page.keyboard.press("Escape");
  await page.waitForTimeout(400);
};

const shadowShot = async (contextOptions, name) => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext(contextOptions);
  await routeAccessHeaders(context, ORIGIN);
  const page = await openBoard(context);
  const { width, height } = page.viewportSize();
  const cx = Math.round(width / 2);
  const cy = Math.round(height / 2);
  await placeSticky(page, cx, cy);
  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) await more.click();
  await page.getByRole("button", { name: "Select tool" }).first().click();
  await page.waitForTimeout(300);
  const path = join(OUT, name);
  await page.screenshot({
    path,
    clip: { x: cx - 160, y: cy - 160, width: 320, height: 320 },
  });
  await context.close();
  await browser.close();
  return path;
};

const rippleShot = async (mode, name) => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  await routeAccessHeaders(context, ORIGIN);
  const page = await openBoard(context);
  const cx = 640;
  const cy = 400;
  await page.mouse.move(cx - 40, cy - 30);
  await page.mouse.down();
  for (let i = 1; i <= 20; i++) await page.mouse.move(cx - 40 + i * 4, cy - 30 + i * 3);
  await page.mouse.up();
  await page.waitForTimeout(800);

  const level = async () =>
    Number(
      (
        await page.locator("[aria-label^='Zoom level ']").first().getAttribute("aria-label")
      ).replace("Zoom level ", ""),
    );
  await page.mouse.move(cx, cy);
  for (let i = 0; i < 80 && (await level()) < 4; i++) {
    await page.mouse.wheel(0, 100);
    await page.waitForTimeout(60);
  }
  await page.waitForTimeout(600);

  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) await more.click();
  await page.getByRole("button", { name: mode }).first().click();
  await page.waitForTimeout(300);

  await page.mouse.move(cx + 460, cy + 350);
  await page.mouse.move(cx + 80, cy);
  await page.waitForTimeout(500);
  const path = join(OUT, name);
  await page.screenshot({ path, clip: { x: cx - 160, y: cy - 120, width: 320, height: 240 } });
  await context.close();
  await browser.close();
  return path;
};

const results = {};
results.stickyDesktop = await shadowShot({ viewport: { width: 1280, height: 800 } }, "sticky-shadow-desktop.png");
results.stickyTablet = await shadowShot({ ...devices["Galaxy Tab S9"] }, "sticky-shadow-tablet.png");
results.rippleMove = await rippleShot("Pan tool", "ripple-move.png");
results.rippleEraser = await rippleShot("Eraser", "ripple-eraser.png");

console.log(JSON.stringify({ results, errors }, null, 2));

