import { createRequire } from "node:module";
import { join } from "node:path";

const WT = "/home/mvhenten/development/stallion-worktrees/sticky-shadow-v2";
const require = createRequire(join(WT, "package.json"));
const { chromium, devices } = require("playwright");
const { routeAccessHeaders } = await import(join(WT, "npm-scripts/env.mjs"));

const OUT = "/home/mvhenten/development/.tmp/stallion-small/shadow-v2";
const ORIGIN = "https://stallion.matthijs-f49.workers.dev";
const label = process.argv[2];
if (!label) {
  console.error("usage: node shadow-shot.mjs <before|after>");
  process.exit(1);
}

const errors = [];

const openBoard = async (context) => {
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && errors.push(`${page.url()}: ${m.text()}`));
  page.on("pageerror", (e) => errors.push(`${page.url()}: ${e}`));
  const id = `shadow${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  await page.goto(`${ORIGIN}/b/${id}`, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
  await page.waitForTimeout(1200);
  return page;
};

const placeSticky = async (page, x, y) => {
  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) await more.click();
  await page.getByRole("button", { name: /^Colours, now/ }).first().click();
  await page.getByRole("button", { name: "Colour 9" }).first().click();
  await page.keyboard.press("Escape");
  await page.waitForTimeout(150);
  const more2 = page.getByRole("button", { name: "More tools" });
  if (await more2.isVisible()) await more2.click();
  await page.getByRole("button", { name: "Sticky note" }).first().click();
  await page.mouse.click(x, y);
  await page.waitForTimeout(300);
  await page.keyboard.type("Shadow proof");
  await page.keyboard.press("Escape");
  await page.waitForTimeout(400);
};

const shot = async (contextOptions, name) => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext(contextOptions);
  await routeAccessHeaders(context, ORIGIN);
  const page = await openBoard(context);
  const { width, height } = page.viewportSize();
  const cx = Math.round(width / 2);
  const cy = Math.round(height / 2);
  await placeSticky(page, cx, cy);
  const more = page.getByRole("button", { name: "More tools" });
  if (await more.isVisible()) await more.click();
  await page.getByRole("button", { name: "Select tool" }).first().click();
  await page.waitForTimeout(200);
  await page.mouse.click(Math.max(cx - 220, 20), Math.max(cy - 220, 20));
  await page.waitForTimeout(300);
  const path = join(OUT, name);
  await page.screenshot({ path, clip: { x: Math.max(cx - 160, 0), y: Math.max(cy - 160, 0), width: 320, height: 320 } });
  await context.close();
  await browser.close();
  return path;
};

const results = {};
results.desktop = await shot({ viewport: { width: 1280, height: 800 } }, `${label}-desktop.png`);
results.tablet = await shot({ ...devices["Galaxy Tab S9"] }, `${label}-tablet.png`);

console.log(JSON.stringify({ results, errors }, null, 2));

